#!/usr/bin/env python3
"""Point 6 -- TCP / contact / force evidence (A diagnostic-only, B/C disabled; nothing re-enabled).

* force_contact_trace.json: the three-state force contact regenerated by this audit run
  (samuele/export_force_contact_annotations.py via the unchanged artifact builder) restricted to
  the clip's unique RGB-D frames, compared with the archived annotation of the earlier report
  (reproducibility), plus the wrench convention / tare / noise provenance.
* Archived Phase A/B/C audits that were not re-executed here are indexed with sha256 and their
  key numbers (tcp_projection_3cam.json, phasec_surface_matches.csv, contact_gradient_observability.json,
  prompt_provenance.csv); each is labelled ``ARCHIVED_NOT_REEXECUTED``.
"""
from __future__ import annotations

import argparse
import csv
import hashlib
import json
from pathlib import Path


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest() if Path(p).is_file() else "MISSING"


def clip_states(annotation_csv, frames, rgbd_to_native):
    """State at each RGB-D frame's native sample (metadata/frame_timestamps.csv: frame_index -> source_frame_index)."""
    rows = list(csv.DictReader(open(annotation_csv)))
    by = {int(float(r["source_frame_index"])): r["contact_state"] for r in rows}
    return {f: by.get(rgbd_to_native.get(f, -1), "MISSING") for f in frames}, "source_frame_index", "contact_state"


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--run", type=Path, required=True)
    ap.add_argument("--camera", default="cam_001")
    ap.add_argument("--archived-annotations", type=Path, required=True)
    ap.add_argument("--archived", type=Path, nargs="*", default=[], help="archived audit JSON/CSV files to index")
    args = ap.parse_args()
    out = args.run / "point6_tcp_contact"
    out.mkdir(parents=True, exist_ok=True)
    data = args.run / "work/datasets" / f"baseline_{args.camera}"
    conv = json.loads((data / "metadata/freeart_conversion.json").read_text())
    frames = [int(r["source_index"]) for r in conv["frame_map"]]
    fc = data / "metadata/force_contact"
    summary = json.loads((fc / "contact_summary.json").read_text())
    ts = Path(conv["scene_root"]) / "metadata/frame_timestamps.csv"
    rgbd_to_native = {int(r["frame_index"]): int(r["source_frame_index"]) for r in csv.DictReader(open(ts))}
    new, key, skey = clip_states(fc / "contact_annotations.csv", frames, rgbd_to_native)
    old, _, _ = clip_states(args.archived_annotations, frames, rgbd_to_native)
    count = lambda d: {s: sum(v == s for v in d.values()) for s in sorted(set(d.values()))}
    trace = dict(scene=conv["scene_root"], frame_mapping="RGB-D frame_index -> native source_frame_index via metadata/frame_timestamps.csv", unique_frames=len(frames), frames=frames,
                 regenerated=dict(file=str(fc / "contact_annotations.csv"), sha256=sha(fc / "contact_annotations.csv"),
                                  counts=count(new), states=new),
                 archived=dict(file=str(args.archived_annotations), sha256=sha(args.archived_annotations), counts=count(old)),
                 identical_states=new == old, differing_frames=[f for f in frames if new[f] != old[f]],
                 thresholds=summary.get("thresholds"), gravity_compensation=summary.get("gravity_compensation"),
                 note=("force magnitude alone does not identify the contacted surface; the visual/force cross-check of "
                       "the earlier report (rigid_motion_corrections_20261116 force_audit.json) is indexed below"))
    (out / "force_contact_trace.json").write_text(json.dumps(trace, indent=1))
    index = []
    for p in args.archived:
        index.append(dict(file=str(p), sha256=sha(p), status="ARCHIVED_NOT_REEXECUTED"))
    (out / "archived_evidence_index.json").write_text(json.dumps(index, indent=1))
    print(json.dumps({k: v for k, v in trace.items() if k in ("identical_states", "differing_frames")}),
          trace["regenerated"]["counts"], trace["archived"]["counts"])


if __name__ == "__main__":
    main()
